import { useMemo } from "react";
import { filterAndRankItems } from "./filterAndRankItems";
export function useFilteredItems(props) {
    const { query, items, filterBy, filter, sortBy, sortingOptions } = props;
    const filteredItems = useMemo(() => {
        return filterAndRankItems({
            query,
            items,
            filterBy,
            filter,
            sortBy,
            sortingOptions,
        });
    }, [query, items, filterBy, filter, sortBy, sortingOptions]);
    return filteredItems;
}
